changeSet.sql:
UPDATE organization SET name_uz = name WHERE name IS NOT NULL AND coalesce(name_uz, name_uz_cyril, name_ru, name_kaa) IS NULL AND name !~ '[А-Яа-яЁё]';
UPDATE organization SET name_uz_cyril = name WHERE name IS NOT NULL AND coalesce(name_uz, name_uz_cyril, name_ru, name_kaa) IS NULL AND name ~ '[ЎўҚқҒғҲҳ]';
UPDATE organization SET name_ru = name WHERE name IS NOT NULL AND coalesce(name_uz, name_uz_cyril, name_ru, name_kaa) IS NULL AND name ~ '[А-Яа-яЁё]';
